{"code": "# Section 6, Q1: Fix score distribution
import json, glob, os
from collections import Counter
from pathlib import Path

ROOT = Path(".")
scores = []
for f in sorted(glob.glob(str(ROOT / "bench/logs/*/runner_state.json"))):
    if os.path.getsize(f) > 60_000_000:
        continue
    try:
        data = json.loads(open(f, errors="ignore").read())
    except:
        continue
    def walk(o):
        if isinstance(o, dict):
            sk = o.get("sk_result")
            if isinstance(sk, dict) and "sk" in sk:
                scores.append(sk["sk"])
            for v in o.values():
                walk(v)
        elif isinstance(o, list):
            for v in o:
                walk(v)
    walk(data)

print(f"Total scored fixes: {len(scores)}")
c = Counter()
for s in scores:
    if s == 1.0:
        c["exactly_1.0"] += 1
    elif s >= 0.99:
        c["0.99_to_1.0"] += 1
    elif s >= 0.9:
        c["0.9_to_0.99"] += 1
    elif s >= 0.8:
        c["0.8_to_0.9"] += 1
    elif s >= 0.7:
        c["0.7_to_0.8"] += 1
    else:
        c["below_0.7"] += 1

for k, v in c.most_common():
    print(f"  {k}: {v} ({v/len(scores)*100:.2f}%)")

# Wilson interval for exactly 1.0
from math import sqrt
z = 1.959963984540054
n = len(scores)
k = c["exactly_1.0"]
p = k/n
d = 1 + z*z/n
c_ = p + z*z/(2*n)
h = z*sqrt(p*(1-p)/n + z*z/(4*n*n))
lo, hi = (c_-h)/d, (c_+h)/d
print(f"\nExactly 1.0: {k}/{n} = {p:.4%}, Wilson [{lo:.4%}, {hi:.4%}]")

# Distribution of non-1.0 scores
non_one = [s for s in scores if s != 1.0]
print(f"\nNon-1.0 scores: {len(non_one)}")
if non_one:
    print(f"  min: {min(non_one):.6f}")
    print(f"  max: {max(non_one):.6f}")
    print(f"  mean: {sum(non_one)/len(non_one):.6f}")
    # histogram
    bins = [0.0, 0.5, 0.6, 0.7, 0.8, 0.9, 0.95, 0.99, 1.0]
    for i in range(len(bins)-1):
        count = sum(1 for s in non_one if bins[i] <= s < bins[i+1])
        print(f"  [{bins[i]:.2f}, {bins[i+1]:.2f}): {count}")"}

